import { useState } from 'react';

type ProductSummary = { id: number; name: string };
type CatalogueState =
  | { status: 'loading' }
  | { status: 'success'; products: ProductSummary[] }
  | { status: 'error'; message: string };

function CatalogueResult({ state }: { state: CatalogueState }) {
  switch (state.status) {
    case 'loading':
      return <p role="status">جارٍ التحميل…</p>;
    case 'error':
      return <p role="alert">{state.message}</p>;
    case 'success':
      return state.products.length === 0
        ? <p>لا توجد منتجات.</p>
        : <ul>{state.products.map(product => <li key={product.id}>{product.name}</li>)}</ul>;
  }
}

type CatalogueProps = { loadProducts: () => Promise<ProductSummary[]> };

export function Catalogue({ loadProducts }: CatalogueProps) {
  const [state, setState] = useState<CatalogueState>({ status: 'success', products: [] });

  async function reload() {
    setState({ status: 'loading' });
    try {
      const products = await loadProducts();
      setState({ status: 'success', products });
    } catch {
      setState({ status: 'error', message: 'تعذر تحميل المنتجات.' });
    }
  }

  return <>
    <button type="button" onClick={reload} disabled={state.status === 'loading'}>تحميل المنتجات</button>
    <CatalogueResult state={state} />
  </>;
}

